using Azure.Storage;
using Azure.Storage.Files.Shares;
using Azure.Storage.Files.Shares.Models;
using System.Collections;
using System.Threading;

/// <summary>
/// Base class for file operations on an Azure file share
/// </summary>
class OMGAzureFileShare
{
    KeyVaultCertificateRef      keyVaultCertificateRef;

}

Method.Source:
/// <summary>
/// Converts a string to a container and removes blank values
/// </summary>
/// <param name = "_string">The string</param>
/// <param name = "_sep">Separator</param>
/// <returns>A container</returns>
public static container str2con(str _string, 
                                str _sep)
{
    container   orig =  str2con(_string, _sep);
    container   ret;
    int         i = 1;
    while (i <= conLen(orig))
    {
        if (conPeek(orig, i) != '')
        {
            ret += conPeek(orig, i);
        }
        i++;
    }

    return ret;
}

public static ShareDirectoryClient getDirectory(ShareClient _shareClient,
                                                str         _directory)
{
    ShareDirectoryClient    shareDirectoryClient;

    shareDirectoryClient = _shareClient.GetDirectoryClient(_directory);

    return shareDirectoryClient;
}

/// <summary>
/// Method to get/set the vertificateRef
/// </summary>
/// <param name = "_keyVaultCertificateRef">The value to set</param>
/// <returns>The value</returns>
public KeyVaultCertificateRef parmKeyVaultCertificateRef(KeyVaultCertificateRef _keyVaultCertificateRef = keyVaultCertificateRef)
{
    keyVaultCertificateRef = _keyVaultCertificateRef;
    return keyVaultCertificateRef;
}
